import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api'; // ajusta el import a tu instancia de axios real

const LAST_BRANCH_KEY = 'pos_last_branch_id';

const LoginPage = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [mode, setMode] = useState('email'); // 'email' | 'pin'
  const [form, setForm] = useState({
    email: '',
    password: '',
    pin_code: '',
    branch_id: localStorage.getItem(LAST_BRANCH_KEY) || '',
  });
  const [branches, setBranches] = useState([]);
  const [branchesLoading, setBranchesLoading] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Solo se cargan las sucursales cuando el usuario entra al modo PIN,
  // para no pegarle al endpoint si nunca lo va a usar.
  useEffect(() => {
    if (mode !== 'pin' || branches.length > 0) return;

    setBranchesLoading(true);
    api.get('/branches/public')
      .then((res) => {
        const list = res.data?.data ?? [];
        setBranches(list);

        // Si la sucursal guardada ya no existe o no hay ninguna guardada,
        // seleccionamos la primera disponible como valor por defecto.
        setForm((prev) => {
          const savedIsValid = list.some((b) => String(b.id) === String(prev.branch_id));
          if (savedIsValid) return prev;
          return { ...prev, branch_id: list[0]?.id ?? '' };
        });
      })
      .catch(() => setError('No se pudieron cargar las sucursales.'))
      .finally(() => setBranchesLoading(false));
  }, [mode, branches.length]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (mode === 'pin' && !form.branch_id) {
      setError('Selecciona una sucursal.');
      return;
    }

    setLoading(true);

    try {
      const credentials = mode === 'email'
        ? { email: form.email, password: form.password }
        : { pin_code: form.pin_code, branch_id: Number(form.branch_id) };

      const user = await login(credentials);

      if (mode === 'pin') {
        localStorage.setItem(LAST_BRANCH_KEY, String(form.branch_id));
      }

      // Redirigir según rol
      if (user.role.level >= 90) navigate('/admin/dashboard');
      else if (user.role.level >= 70) navigate('/admin/dashboard');
      else if (user.role.slug === 'chef') navigate('/kitchen');
      else if (user.role.slug === 'cashier') navigate('/cashier');
      else if (user.role.slug === 'waiter') navigate('/waiter');
      else navigate('/');

    } catch (err) {
      setError(err.response?.data?.message || 'Error al iniciar sesión');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%)',
      padding: '20px',
    }}>
      <div className="card" style={{ width: '100%', maxWidth: 420, textAlign: 'center' }}>
        <div style={{ fontSize: 48, marginBottom: 10 }}>🍽️</div>
        <h1 style={{ color: '#38bdf8', marginBottom: 4, fontSize: 24 }}>Restaurant AR</h1>
        <p style={{ color: '#94a3b8', marginBottom: 30, fontSize: 14 }}>Sistema de Gestión Gastronómica</p>

        {/* Toggle modo */}
        <div style={{
          display: 'flex',
          gap: 8,
          marginBottom: 24,
          background: '#0f172a',
          padding: 4,
          borderRadius: 10,
        }}>
          <button
            onClick={() => setMode('email')}
            style={{
              flex: 1,
              padding: '10px',
              borderRadius: 8,
              border: 'none',
              background: mode === 'email' ? '#38bdf8' : 'transparent',
              color: mode === 'email' ? '#0f172a' : '#94a3b8',
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s',
            }}
          >
            Email
          </button>
          <button
            onClick={() => setMode('pin')}
            style={{
              flex: 1,
              padding: '10px',
              borderRadius: 8,
              border: 'none',
              background: mode === 'pin' ? '#38bdf8' : 'transparent',
              color: mode === 'pin' ? '#0f172a' : '#94a3b8',
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s',
            }}
          >
            PIN Rápido
          </button>
        </div>

        {error && (
          <div style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid #ef4444',
            color: '#ef4444',
            padding: '12px',
            borderRadius: 10,
            marginBottom: 20,
            fontSize: 14,
          }}>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          {mode === 'email' ? (
            <>
              <input
                type="email"
                placeholder="Correo electrónico"
                className="input"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                style={{ marginBottom: 12 }}
                required
              />
              <input
                type="password"
                placeholder="Contraseña"
                className="input"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                style={{ marginBottom: 20 }}
                required
              />
            </>
          ) : (
            <>
              <select
                className="input"
                value={form.branch_id}
                onChange={(e) => setForm({ ...form, branch_id: e.target.value })}
                style={{ marginBottom: 12 }}
                required
                disabled={branchesLoading}
              >
                <option value="" disabled>
                  {branchesLoading ? 'Cargando sucursales...' : 'Selecciona tu sucursal'}
                </option>
                {branches.map((branch) => (
                  <option key={branch.id} value={branch.id}>
                    {branch.name}
                  </option>
                ))}
              </select>

              <input
                type="password"
                inputMode="numeric"
                placeholder="Ingresa tu PIN"
                className="input"
                value={form.pin_code}
                onChange={(e) => setForm({ ...form, pin_code: e.target.value.replace(/\D/g, '') })}
                style={{ marginBottom: 20, fontSize: 24, textAlign: 'center', letterSpacing: 8 }}
                maxLength={6}
                required
              />
            </>
          )}

          <button
            type="submit"
            className="btn btn-primary"
            style={{ width: '100%', padding: 14, fontSize: 16 }}
            disabled={loading || (mode === 'pin' && branches.length === 0)}
          >
            {loading ? 'Ingresando...' : 'Ingresar'}
          </button>
        </form>

        <p style={{ color: '#64748b', marginTop: 20, fontSize: 12 }}>
          ¿Eres cliente? <a href="/menu/SUC-001" style={{ color: '#38bdf8' }}>Ver menú digital</a>
        </p>
      </div>
    </div>
  );
};

export default LoginPage;
